import { useStore } from '~/app/store/store';
import { AppParams } from '~/entities/super-app/model/types';
import { useSendSuperAppCommand } from '~/shared/lib/hooks/super-app/use-send-super-app-command';
import { useSetHeaderLeft } from '~/widgets/sub-layout/use-sub-layout';
import { useTxSearchMutation } from '~/entities/exchange/api/hooks/use-tx-search-mutation';
import { useExchangeNavigation } from '~/entities/exchange/lib/use-exchange-navigation';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { PinInterface } from '~/entities/pin/ui/pin-interface';
import {
  PinInteractionMode,
  SuperAppCommandInbound,
  SuperAppCommandOutbound,
  SuperAppResultCode,
  TrnscTypeCd,
} from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const LoginPinNumberPage = () => {
  const { routerState: state } = useGetRouterState<AppParams>();
  const { navigate } = useNavigate();
  const { sendSuperAppCommand } = useSendSuperAppCommand();
  const { openAlertDialog } = useAlertDialog();
  const { mutateAsync: txSearch } = useTxSearchMutation({ throwOnError: false });
  const { navigateToExchange } = useExchangeNavigation();
  useSetHeaderLeft(<></>);

  return (
    <PinInterface
      type={PinInteractionMode.로그인}
      title={i18n.t('pin:titlePin')}
      message={i18n.t('pin:messageInputPin')}
      handleCompleteInput={async () => {
        if (state?.command === SuperAppCommandInbound.앱to앱_결제요청) {
          // txCd로 결제 정보 조회
          const tbPayMastr = await txSearch({ tbPayMastr: { txCd: state.txCode! } });
          //console.log('tbPayMastr', tbPayMastr);
          if (!tbPayMastr) {
            openAlertDialog({
              message: i18n.t('text:paymentErrorText'),
              onConfirmClick: () => {
                sendSuperAppCommand({
                  command: SuperAppCommandOutbound.슈퍼앱_에러콜백,
                  resultCode: SuperAppResultCode.지갑존재,
                });
              },
            });
            return;
          }

          navigateToExchange({
            tbPayMastr,
            command: state.command,
            txCd: state.txCode ?? '',
            isAppToApp: true,
            isQrScan: false,
            trnscTypeCd: TrnscTypeCd.결제,
          }).then(() => {
            // 앱to앱 결제시 부모창은 결제창을 띄운 이후 존재하면 안되므로 close시킴.
            window.close();
          });
        } else {
          useStore.getState().superAppSlice.clearSuperAppData();
          navigate(PATHS.home, { replace: true });
        }
      }}
    />
  );
};
